package wgmodern;
import java.util.*;import net.minecraft.gametest.framework.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.core.*;import net.minecraft.world.item.*;import net.minecraft.nbt.CompoundTag;import net.minecraftforge.gametest.*;import tc4revival.content.*;import tc4revival.aspect.*;
@GameTestHolder("witchinggadgets") @PrefixGameTestTemplate(false)
public class OptionalIntegrationTests {
 @GameTestGenerator public static Collection<TestFunction> installedIntegrations(){var tests=new ArrayList<TestFunction>();var mods=net.minecraftforge.fml.ModList.get();if(mods.isLoaded("cb_multipart")){tests.add(test("multipart_native_transport",MultipartChecks::nativeTransport));tests.add(test("multipart_conversion_and_occlusion",MultipartChecks::conversion));}if(mods.isLoaded("botania")){tests.add(test("botania_cosmetic_round_trip",OptionalIntegrationTests::cosmetics));tests.add(test("botania_cosmetic_crafting_returns_decoration",OptionalIntegrationTests::cosmeticCrafting));}if(mods.isLoaded("tconstruct"))tests.add(test("tconstruct_cluster_units_and_aspects",OptionalIntegrationTests::melting));if(mods.isLoaded("rackitup"))tests.add(test("rackitup_brain_drying",OptionalIntegrationTests::drying));return tests;}
 private static TestFunction test(String name,java.util.function.Consumer<GameTestHelper> run){return new TestFunction("wg_optional","witchinggadgets."+name,"witchinggadgets:empty",200,0,true,run);}
 public static class MultipartChecks {
  public static void nativeTransport(GameTestHelper h){var l=h.getLevel();var p=h.absolutePos(new BlockPos(2,3,2));l.setBlockAndUpdate(p.below(),TCArcane.ESSENTIA_JAR.get().defaultBlockState());var part=new MultipartCompat.Tube(EssentiaTubeFlow.Kind.BUFFER);codechicken.multipart.block.TileMultipart.addPart(l,p,part);var be=l.getBlockEntity(p);h.assertTrue(be instanceof EssentiaTransport&&be instanceof WandInteractable&&be instanceof RevealedAspectContainer,"Multipart forwards all three native contracts");var a=TCAspects.catalog().require("aer");for(int i=0;i<8;i++)h.assertTrue(((EssentiaTransport)be).addEssentia(a,1,Direction.UP)==1,"Native one-unit fill reaches multipart buffer");h.runAfterDelay(55,()->{var jar=(EssentiaJarBlockEntity)l.getBlockEntity(p.below());h.assertTrue(jar.amount()==8&&jar.aspect().equals(a)&&part.flow.contents().isEmpty(),"Real native jar tick empties the shared-space buffer without duplication");pass(h);});}
  public static void conversion(GameTestHelper h){var l=h.getLevel();var p=h.absolutePos(new BlockPos(2,2,2));l.setBlockAndUpdate(p,TCArcane.ESSENTIA_FILTER.get().defaultBlockState());var nativeTube=(EssentiaTubeBlockEntity)l.getBlockEntity(p);var a=TCAspects.catalog().require("ignis");nativeTube.flow().filter(a);nativeTube.flow().setOpen(Direction.WEST,false);nativeTube.flow().addEssentia(a,1,Direction.EAST);var converted=new MultipartCompat.Converter().convert(l,p,l.getBlockState(p));h.assertTrue(converted.success()&&converted.result().size()==1,"All native filter state can convert");var part=(MultipartCompat.Tube)converted.result().iterator().next();h.assertTrue(part.flow.filter().equals(a)&&!part.flow.open(Direction.WEST)&&part.flow.contents().amount(a)==1,"Conversion retains filter, closed port and contained essentia");var nbt=new CompoundTag();part.save(nbt);var restored=new MultipartCompat.Tube(EssentiaTubeFlow.Kind.FILTER);restored.load(nbt);h.assertTrue(restored.flow.filter().equals(a)&&restored.flow.contents().amount(a)==1,"Multipart persistence retains transport state");h.assertTrue(part.occlusionTest(new MultipartCompat.Probe(net.minecraft.world.level.block.Block.box(0,0,0,16,2,16)))&&!part.occlusionTest(new MultipartCompat.Probe(net.minecraft.world.level.block.Block.box(6,6,6,10,10,10))),"A face cover fits but intersecting center parts do not");pass(h);}
 }
 public static void cosmetics(GameTestHelper h){var cosmetic=net.minecraftforge.registries.ForgeRegistries.ITEMS.getValue(new ResourceLocation("botania","cosmetic_black_bowtie"));h.assertTrue(cosmetic!=null&&cosmetic!=Items.AIR,"Installed Botania cosmetic found");for(var item:List.of(Content.CLOAKS.get("cloak_storage").get(),Content.GEAR.get("shoulders_base").get())){var s=new ItemStack(item);s.getOrCreateTag().putString("ownerName","preserved");var attach=(vazkii.botania.api.item.CosmeticAttachable)item;attach.setCosmeticItem(s,new ItemStack(cosmetic));var copy=ItemStack.of(s.save(new CompoundTag()));h.assertTrue(attach.getCosmeticItem(copy).is(cosmetic),"Actual Botania interface persists cosmetic");attach.setCosmeticItem(copy,ItemStack.EMPTY);h.assertTrue(attach.getCosmeticItem(copy).isEmpty()&&!attach.getCosmeticItem(s).isEmpty()&&copy.getTag().getString("ownerName").equals("preserved"),"Removal changes only the copied cosmetic");}pass(h);}
 public static void cosmeticCrafting(GameTestHelper h){
  var player=net.minecraftforge.common.util.FakePlayerFactory.getMinecraft(h.getLevel());
  var grid=new net.minecraft.world.inventory.TransientCraftingContainer(player.inventoryMenu,2,2);
  var registry=net.minecraftforge.registries.ForgeRegistries.ITEMS;
  var cosmetic=registry.getValue(new ResourceLocation("botania","cosmetic_black_bowtie"));
  for(var item:List.of(Content.CLOAKS.get("cloak_storage").get(),Content.GEAR.get("shoulders_base").get(),registry.getValue(new ResourceLocation("botania","mana_ring")))){
   grid.clearContent();var original=new ItemStack(item);original.getOrCreateTag().putString("ownerName","preserved");
   var decoration=new ItemStack(cosmetic);decoration.getOrCreateTag().putString("testMarker","original");
   grid.setItem(0,original);grid.setItem(1,decoration);
   var attach=h.getLevel().getRecipeManager().getRecipeFor(net.minecraft.world.item.crafting.RecipeType.CRAFTING,grid,h.getLevel()).orElseThrow();
   var decorated=attach.assemble(grid,h.getLevel().registryAccess());
   h.assertTrue(decorated.getItem() instanceof vazkii.botania.api.item.CosmeticAttachable,"Actual attach recipe produces wearable");
   var api=(vazkii.botania.api.item.CosmeticAttachable)decorated.getItem();
   h.assertTrue(api.getCosmeticItem(decorated).is(cosmetic),"Actual attach recipe retains decoration");
   grid.clearContent();grid.setItem(2,decorated);
   var remove=h.getLevel().getRecipeManager().getRecipeFor(net.minecraft.world.item.crafting.RecipeType.CRAFTING,grid,h.getLevel()).orElseThrow();
   var clean=remove.assemble(grid,h.getLevel().registryAccess());var rest=remove.getRemainingItems(grid);
   h.assertTrue(clean.is(item)&&api.getCosmeticItem(clean).isEmpty()&&clean.getTag().getString("ownerName").equals("preserved"),"Removal preserves wearable and unrelated NBT");
   h.assertTrue(rest.get(2).is(cosmetic)&&rest.get(2).getCount()==1&&rest.stream().filter(x->!x.isEmpty()).count()==1,"Actual removal returns exactly one decoration in its input slot");
   h.assertTrue(rest.get(2).getTag().getString("testMarker").equals("original"),"Returned decoration retains NBT");
   // Our remainder must be copied; Botania's native BaubleItem returns its own nested tag directly.
   if(item instanceof CloakItem||item instanceof WGAccessories.Gear){
    rest.get(2).getTag().putString("testMarker","changed");
    h.assertTrue(api.getCosmeticItem(decorated).getTag().getString("testMarker").equals("original"),"Remainder is independent of input NBT: "+registry.getKey(item));
   }
  }
  pass(h);
 }
 public static void melting(GameTestHelper h){var l=h.getLevel();var r=l.getRecipeManager().byKey(new ResourceLocation("witchinggadgets","compat/melting/iron")).orElseThrow();try{var fluid=(net.minecraftforge.fluids.FluidStack)r.getClass().getMethod("getOutput").invoke(r);h.assertTrue(fluid.getAmount()==270&&net.minecraftforge.registries.ForgeRegistries.FLUIDS.getKey(fluid.getFluid()).toString().equals("tconstruct:molten_iron"),"Original three ingots become exactly 270 modern mB");}catch(ReflectiveOperationException e){throw new RuntimeException(e);}var cobalt=BlastRecipe.tagged("forge:ingots/cobalt",1);var direct=tc4revival.aspect.item.ItemAspects.direct(cobalt).orElseThrow();h.assertTrue(direct.amount(TCAspects.catalog().require("metallum"))==3&&direct.amount(TCAspects.catalog().require("ignis"))==1&&direct.amount(TCAspects.catalog().require("motus"))==1,"Old cobalt tag aspects expanded against installed TCon items");pass(h);}
 public static void drying(GameTestHelper h){var r=h.getLevel().getRecipeManager().byKey(new ResourceLocation("witchinggadgets","compat/brainjerky")).orElseThrow();try{var ingredient=(net.minecraft.world.item.crafting.Ingredient)r.getClass().getMethod("getIngredient").invoke(r);int ticks=(int)r.getClass().getMethod("getDryingTime").invoke(r);h.assertTrue(r.getResultItem(h.getLevel().registryAccess()).is(Content.BRAINJERKY.get())&&ingredient.test(new ItemStack(TCItems.ZOMBIE_BRAIN.get()))&&ticks==600,"Installed drying rack accepts zombie brain and produces original jerky after 600 ticks");}catch(ReflectiveOperationException e){throw new RuntimeException(e);}pass(h);}
 private static void pass(GameTestHelper h){com.mojang.logging.LogUtils.getLogger().info("WITCHINGGADGETS_OPTIONAL_TEST_PASS {}",Thread.currentThread().getStackTrace()[2].getMethodName());h.succeed();}
}
